import{promises as fs}from'node:fs';for(const p of['scripts/build.mjs','assets/atlas.css'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}. Repo kökünde çalıştır.`)});const append=async(f,p,m)=>{let s=await fs.readFile(f,'utf8');if(!s.includes(m)){s+='\n'+await fs.readFile(p,'utf8');await fs.writeFile(f,s)}};await append('scripts/build.mjs','v23-2-build-patch.txt','V23.2 remove duplicate audio readers');await append('assets/atlas.css','v23-2-css-patch.txt','V23.2 remove black bars');await fs.copyFile('article-reader-v232.js','assets/article-reader-v232.js');console.log('V23.2 kuruldu: yinelenen ses paneli ve siyah boşluk temizlendi.');
